					} `json:"message"`
				} `json:"choices"`
			}
			if err := json.Unmarshal(buf.Bytes(), &raw); err == nil {
				if len(raw.Choices) > 0 {
					synthesis = raw.Choices[0].Message.Content
				}
			}
		}
	}
	if fetchErr != nil {
		return outcome, false, fmt.Errorf("fusion: arbiter fetch: %w", fetchErr)
	}
	if synthesis == "" {
